function projects(){title.textContent='Projects are the anchor.';eyebrow.textContent='PROJECTS';const ps=orderedProjects(filter(data.projects));const other=orderedProjects(filter((data.repositories||[]).filter(p=>p.repositoryClass!=='Project'&&p.repositoryClass!=='Hidden')));app.innerHTML=`<section class="panel list-panel"><div class="section-head"><div><h3>${ps.length} projects</h3><p>Pin what matters, set a local status, and leave a short private note.</p></div></div>${ps.map(projectRow).join('')||empty('No matching projects.')}</section>${other.length?`<details class="repository-inventory"><summary><span>Other repositories</span><b>${other.length}</b></summary><p>Tool and reference repositories remain indexed for attribution, but stay out of Projects and Continue Working.</p>${other.map(repositoryRow).join('')}</details>`:''}`;bind()}
function resumeFacts(p,lastAgent,rec){return `<dl class="resume-facts"><dt>Last activity</dt><dd>${esc(lastAgent?`${lastAgent}${p.git?.branch?` · ${p.git.branch}`:''} · ${ago(p.recentActivity)}`:'No attributed agent activity')}</dd><dt>Latest commit</dt><dd>${esc(p.git?.lastCommitSubject||'No Git commit found')}</dd><dt>Working tree</dt><dd>${p.git?.dirty===true?'Uncommitted changes':p.git?.dirty===false?'Clean':'Unavailable'}</dd><dt>Recommendation</dt><dd>${esc(rec.reason||'No stronger local signal is available.')}</dd></dl>`}
function projectDetail(p){detailId=p.id;const ss=data.sessions.filter(s=>s.projectId===p.id&&eligible(s));const resumeInfo=operator?.resume?.find(item=>item.project.id===p.id);const last=ss.sort((a,b)=>String(b.timestamp).localeCompare(String(a.timestamp)))[0];const lastAgent=resumeInfo?.lastAgent||last?.agent||null;const rec=resumeInfo?.recommendation||{agent:lastAgent||'Cursor',reason:lastAgent?`${lastAgent} was the last agent used on this project.`:'No stronger local signal is available.'};title.textContent=p.name;eyebrow.textContent='PROJECT';app.innerHTML=`<button class="back" data-back="projects">← Back to Projects</button><section class="project-hero"><div><h2>${esc(p.name)}</h2><p>${esc(p.agents.length?p.agents.join(' · '):'Git activity only')} · ${esc(p.hosts.join(' · ')||'host unavailable')}</p></div><div>${p.status?chip(p.status,'status'):chip('No status','muted')} <button class="pin detail-pin" data-pin="${p.id}" aria-pressed="${p.pinned}">${p.pinned?'Unpin project':'Pin project'}</button></div></section><section class="resume-context panel"><div class="section-head"><div><h3>Resume Context</h3><p>Observed from Git and session metadata. Prompts and transcripts are never included.</p></div></div>${resumeFacts(p,lastAgent,rec)}<div class="resume-actions">${['Claude','Codex','Cursor'].map(agent=>`<button class="filter" data-open-agent="${agent}" data-open-project="${p.id}" ${agentAvailable(agent)?'':'disabled'} title="${agentAvailable(agent)?'':`${agent} CLI is not installed on this machine`}">Open in ${agent}</button>`).join('')}<button class="primary" data-handoff="${p.id}">Generate handoff</button></div><pre id="handoff-preview" class="handoff-preview" hidden></pre></section><section class="project-memory panel"><div class="section-head"><div><h3>Your working memory</h3><p>Private to this dashboard. Never exported or shared.</p></div></div><div class="memory-grid"><label>Status<select id="project-status"><option value="">No status</option>${['Active','Paused','Waiting','Done','Archived'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="note-label">Your note<textarea id="project-note" maxlength="500" placeholder="What should you remember when you return?">${esc(p.note||'')}</textarea></label></div><div class="memory-actions"><button class="primary" id="save-project-memory">Save locally</button><label class="repository-class">Repository type<select id="repository-class">${['Project','Tool','Reference','Hidden'].map(x=>`<option ${p.repositoryClass===x?'selected':''}>${x}</option>`).join('')}</select></label></div></section><div class="metrics-grid">${card('AI sessions',fmt(p.sessionCount),'confirmed or strongly inferred')}${card('Token activity',short(total(p.tokens)),'all observed token categories')}${card('Git commits',fmt(p.metrics.commits),'repository history')}${card('Active days',fmt(new Set(ss.map(s=>s.timestamp?.slice(0,10))).size),'session activity')}</div><section class="panel"><div class="section-head"><div><h3>Recent AI activity</h3><p>Separate from your note; derived from local session metadata.</p></div></div>${ss.length?`<div class="activity-summary">${agentIdentity(lastAgent||ss.at(-1).agent)}<strong>${fmt(ss.length)} sessions</strong><small>${ago(ss.at(-1).timestamp)} → ${ago(ss[0].timestamp)}</small></div>`:''}${ss.slice(-5).reverse().map(s=>`<div class="session-row"><span>${esc(s.agent)} <small>in ${esc(s.host||s.agent)}${s.model?` · ${esc(s.model)}`:''}</small></span><span>${chip(s.attributionConfidence,s.attributionConfidence==='Confirmed'?'':'muted')}</span><time>${ago(s.timestamp)}</time></div>`).join('')||empty('No attributed sessions.')}</section>`;bind();document.querySelector('#save-project-memory').onclick=async()=>{await saveProjectMetadata(p.id,{status:document.querySelector('#project-status').value||null,note:document.querySelector('#project-note').value,pinned:p.pinned,repositoryClass:document.querySelector('#repository-class').value});data=await(await fetch('/api/data')).json();const next=project(p.id);if(next.repositoryClass==='Project')projectDetail(next);else{detailId=null;projects()}}}
function filterButton(label, selected, attrs){return `<button class="filter-chip ${selected?'selected':''}" ${attrs}>${esc(label)}</button>`}
function instructionsByScope(items){const groups=new Map();for(const item of items){const key=item.scope==='Project-specific'?(item.components.find(x=>x.projectId)?.projectId||'Project'):(item.scope||'Shared');const label=item.scope==='Project-specific'?(data.repositories||[]).find(p=>p.id===key)?.name||'Project instructions':key==='User / Global'?'Global / user':'Shared';(groups.get(label)||groups.set(label,[]).get(label)).push(item)}return [...groups.entries()].map(([label,values])=>`<section class="instruction-group"><h4>${esc(label)}</h4>${values.map(capabilityRow).join('')}</section>`).join('')}
function capabilities(){title.textContent='Your AI capability stack.';eyebrow.textContent='CAPABILITIES';const typeMatches=c=>capType==='All functionality'?c.type!=='Instructions':c.type===capType;const caps=orderedCapabilities(filter(data.capabilities).filter(c=>typeMatches(c)&&(capScope==='All'||c.scope===capScope)));const content=componentMode?filter(data.rawCapabilities).map(componentRow).join(''):capType==='Instructions'?instructionsByScope(caps):caps.map(capabilityRow).join('');app.innerHTML=`<section class="registry-head"><div><h2>Useful things, clearly separated.</h2><p>Reusable functionality stays in front. Instructions are available when you need to manage them.</p></div><span class="quiet">${data.rawCapabilities.length} observed components</span></section><div class="filter-groups"><div>${['All functionality','Skills','Tools','Integrations','Automation','Instructions'].map(x=>filterButton(x,capType===x,`data-cap-type="${x}"`)).join('')}</div><div>${['All','Shared','User / Global','Custom','Project-specific'].map(x=>filterButton(x,capScope===x,`data-cap-scope="${x}"`)).join('')}<button class="text-action components-button" id="components-toggle">${componentMode?'Back to capabilities':'View components'}</button></div></div><section class="panel list-panel"><div class="section-head"><div><h3>${caps.length} ${capType==='Instructions'?'instructions':'capabilities'}</h3><p>${componentMode?'Advanced audit view of discovered files and command references.':capType==='Instructions'?'Organized by scope; raw paths stay in details.':'Recognizable parent capabilities are shown by default.'}</p></div></div><div id="cap-list">${content||empty('No capabilities match this search or filter.')}</div></section>`;bind();document.querySelectorAll('[data-cap-type]').forEach(b=>b.onclick=()=>{capType=b.dataset.capType;render()});document.querySelectorAll('[data-cap-scope]').forEach(b=>b.onclick=()=>{capScope=b.dataset.capScope;render()});document.querySelector('#components-toggle').onclick=()=>{componentMode=!componentMode;render()}}
function orderedCapabilities(caps){return [...caps].sort((a,b)=>Number(b.usageCount)-Number(a.usageCount)||a.name.localeCompare(b.name))}
function componentRow(c){return `<div class="component"><strong>${esc(c.name)}</strong><small>${esc(c.type)} · ${esc(c.origin)}</small><small>${esc(c.statusNote)}</small></div>`}
function capabilityRow(c){return `<button class="cap-row" data-capability="${c.id}"><span class="cap-icon ${c.type.toLowerCase()}">${c.type.slice(0,1)}</span><span class="cap-copy"><strong>${esc(c.name)}</strong><small>${esc(c.description||'Installed capability')} · ${c.components.length} observed parts</small><em>${chip(c.type,'type')} ${chip(c.scope,'scope')}</em></span><span>${chip(c.artifactState,'artifact')} ${chip(c.health,c.health==='Active'?'pink':'muted')}</span><time>${c.lastUsedAt?ago(c.lastUsedAt):c.active?'Active configuration':'No observed use'}</time></button>`}
function coverageRows(c){return c.agentCoverage.map(x=>`<div class="coverage-row"><strong>${x.agent}</strong><span>${x.state}</span></div>`).join('')}
function automationDetails(c){if(c.type!=='Automation')return '';return `<section class="panel automation-details"><div class="section-head"><div><h3>Automatic behavior</h3><p>Native configuration observed read-only.</p></div></div><dl><dt>Agent</dt><dd>${esc(c.agent||'Unknown')}</dd><dt>Trigger</dt><dd>${esc(c.trigger||'Unknown')}</dd><dt>Behavior</dt><dd>${esc(c.behavior||c.description)}</dd><dt>Implementation</dt><dd>${esc(c.implementation||'Unknown')}</dd><dt>Portability</dt><dd>${esc(c.portability||'Unknown')}</dd></dl></section>`}
function capabilityDetail(c){title.textContent=c.name;eyebrow.textContent='CAPABILITY';const observed=c.recentUsage||[],components=c.componentGroups||[];app.innerHTML=`<button class="back" data-back="capabilities">← Back to Capabilities</button><section class="detail-top"><div><div class="cap-labels">${chip(c.type,'type')} ${chip(c.scope,'scope')}</div><h2>${esc(c.name)}</h2><p>${esc(c.description||'No safe source description is available.')}</p></div>${chip(c.health,c.health==='Active'?'pink':'muted')}</section><div class="metrics-grid">${card('Artifact state',c.artifactState,'known installation evidence')}${card('Installed on',c.installedOn.join(' · ')||'No agent installation found','detected local locations')}${card('Compatible with',c.compatibleAgents.join(' · ')||'Compatibility unknown','only supported evidence is shown')}${card('Last observed',c.lastUsedAt?ago(c.lastUsedAt):c.active?'Active configuration':'No confirmed use','available local history')}</div>${automationDetails(c)}<div class="wide-grid capability-sections"><section class="panel"><div class="section-head"><div><h3>Installation coverage</h3><p>Artifact completeness and agent coverage are separate.</p></div></div>${coverageRows(c)}<div class="install-components">${c.installationComponents.map(x=>`<span>${esc(x.name)} <b>${x.count}</b> <small>observed</small></span>`).join('')}</div></section><section class="panel"><div class="section-head"><div><h3>Capability history</h3><p>Observed events only; not a maintenance queue.</p></div></div>${c.history.map(x=>`<div class="history-row"><span>${esc(x.type)}</span><div><strong>${esc(x.label)}</strong><small>${esc(x.confidence)}</small></div><time>${ago(x.timestamp)}</time></div>`).join('')||empty('No reliable capability history is available yet.')}</section></div><section class="panel capability-components"><div class="section-head"><div><h3>Components</h3><p>Grouped source artifacts. Expand only when you need the raw discovery record.</p></div></div>${components.map(x=>`<div class="feature-row"><span><strong>${esc(x.name)}</strong><small>${esc(x.type)} · ${x.count} component${x.count===1?'':'s'}</small></span><b>${x.usageCount||'—'}</b><small>${x.usageCount?'confirmed uses':'not usage evidence'}</small></div>`).join('')||empty('No observed components.')}</section><section class="panel observed-usage"><div class="section-head"><div><h3>Observed usage</h3><p>Only confirmed structured invocation evidence appears here.</p></div></div>${observed.length?observed.map(x=>`<div class="feature-row"><span><strong>${esc(x.agent)}</strong><small>${esc(x.contextLabel||'Structured capability invocation')}</small></span><b>${ago(x.timestamp)}</b><small>${esc(x.confidence)}</small></div>`).join(''):empty('No confirmed use has been found in the available local history.')}</section><details class="tech"><summary>Installation & ownership details</summary><p>Known artifacts are mapped for future safe management. Nothing is automatically changed.</p><ul>${c.installation.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><p>${esc(c.ownership.management)}</p></details>`;bind()}
function maintenanceCard(c){const r=c.reason;const duplicate=Array.isArray(c.items);return `<article class="maintenance-item"><span class="cap-icon ${(c.type||'Tools').toLowerCase()}">${(c.type||'Tools').slice(0,1)}</span><div><strong>${esc(c.name)}</strong><p><b>${esc(r.label)}.</b> ${duplicate?`${c.items.length} installed copies`: `${esc(c.type)} · ${esc(c.scope)}`}</p>${duplicate?`<dl><dt>Where</dt><dd>${esc(c.items.map(x=>x.origin||'Local installation').join(' · '))}</dd><dt>Evidence</dt><dd>${c.kind==='Exact duplicate'?'Matching content hashes.':'Different installation keys or source origins.'}</dd><dt>Impact</dt><dd>${esc(r.impact)}</dd><dt>Next</dt><dd>${esc(r.next)}</dd></dl>`:`<dl><dt>Impact</dt><dd>${esc(r.impact)}</dd><dt>Next</dt><dd>${esc(r.next)}</dd></dl>`}</div><button class="text-action" ${duplicate?`data-duplicate="${c.id}"`:`data-capability="${c.id}"`}>${duplicate?'Investigate':'View capability'}</button></article>`}
function duplicateDetail(item){title.textContent=item.name;eyebrow.textContent='DUPLICATE INVESTIGATION';app.innerHTML=`<button class="back" data-back="maintenance">← Back to Maintenance</button><section class="detail-top"><div><h2>${esc(item.name)}</h2><p>${esc(item.reason.label)}. Read-only comparison; nothing will be removed.</p></div>${chip(item.kind,'type')}</section><section class="panel"><div class="section-head"><div><h3>Installed copies</h3><p>Compare ownership and source evidence before creating any resolution plan.</p></div></div>${item.items.map(copy=>`<div class="duplicate-copy"><strong>${esc(copy.origin||'Local installation')}</strong><span>${esc(copy.installedOn?.join(' · ')||'Agent coverage unknown')}</span><small>${copy.exactFiles?'Exact content duplicate':'Hash/version differs or is incomplete'} · ${copy.lastModified?ago(copy.lastModified):'Modified time unavailable'} · ${copy.usageCount||0} confirmed uses</small></div>`).join('')}</section><section class="panel"><div class="section-head"><div><h3>Review resolution</h3><p>A future repair plan will list exact owned artifacts and rollback information. This version only investigates.</p></div></div>${empty('No automatic removal or repair is available for this finding.')}</section>`;bind()}
function maintenanceSection(title,items,open=false){if(!items?.length)return '';return `<details class="maintenance-section" ${open?'open':''}><summary><span>${esc(title)}</span><b>${items.length}</b></summary><div>${items.map(maintenanceCard).join('')}</div></details>`}
function maintenance(){title.textContent='Things worth reviewing.';eyebrow.textContent='MAINTENANCE';const m=data.maintenance||{},urgent=(m.needsAction||[]).length+(m.updates||[]).length+(m.duplicates||[]).length;app.innerHTML=`<section class="maintenance-intro"><h2>${urgent?'A few items need attention.':'Nothing urgent is broken.'}</h2><p>Broken, partial, and possible duplicate capabilities come first. Unused capabilities stay collapsed — this dashboard inventories them and does not install or sync skills. Use Skiller if you need an installer.</p></section><div class="maintenance-groups">${maintenanceSection('Needs action',m.needsAction,true)}${maintenanceSection('Possible duplicates',m.duplicates,Boolean(m.duplicates?.length))}${maintenanceSection('Updates',m.updates,true)}${maintenanceSection('Installation coverage',m.coverage,false)}${maintenanceSection('Usage review',m.usageReview,false)||empty('No maintenance items from current conservative rules.')}</div>`;bind()}
function setHeaderUtility(){document.querySelector('#setup').setAttribute('aria-expanded',String(utility==='setup'));document.querySelector('#share').setAttribute('aria-expanded',String(utility==='share'))}
function toggleDrawer(kind){if(utility===kind){closeDrawer();return;}closeDrawer();openDrawer(kind)}
function openDrawer(kind){utility=kind;const layer=document.createElement('div');layer.id='utility-layer';layer.innerHTML=`<button class="drawer-scrim" aria-label="Close ${kind==='setup'?'export setup':'share stats'}"></button><aside id="drawer" class="drawer-${kind}" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="drawer-head"><div><span class="kicker">${kind==='setup'?'EXPORT MY AI STACK':'SHARE STATS'}</span><h2 id="drawer-title">${kind==='setup'?'Take your setup with you.':'Your development story.'}</h2></div><button class="close" aria-label="Close">×</button></div><div id="drawer-content"></div></aside>`;document.body.classList.add('utility-open');document.body.append(layer);layer.querySelector('.close').onclick=closeDrawer;layer.querySelector('.drawer-scrim').onclick=closeDrawer;keyHandler=e=>{if(e.key==='Escape')closeDrawer()};document.addEventListener('keydown',keyHandler);setHeaderUtility();kind==='setup'?setupDrawer(layer):recapShareDrawer(layer)}
function closeDrawer(){utilityCleanup?.();utilityCleanup=null;document.querySelector('#utility-layer')?.remove();document.body.classList.remove('utility-open');if(keyHandler)document.removeEventListener('keydown',keyHandler);keyHandler=null;utility=null;setHeaderUtility()}
async function setupDrawer(layer){const c=layer.querySelector('#drawer-content');c.innerHTML=`<p class="drawer-intro">Choose the format that fits your goal. Public exports never include project names, notes, paths, prompts, transcripts, or credentials.</p><div class="goal-list"><button data-export="stack"><strong>Share Stack</strong><span>A privacy-safe representation of the agents and capabilities you use.</span></button><button data-prompt><strong>Setup Prompt</strong><span>A current prompt for another AI agent to safely audit and adapt this stack.</span></button><button data-export="manifest"><strong>Manifest</strong><span>Machine-readable interoperability for a future dashboard import.</span></button><button data-export="private"><strong>Private Backup</strong><span>Detailed local audit inventory. Never share.</span></button></div><div id="prompt-preview"></div>`;c.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>download(await(await fetch(`/api/export/${b.dataset.export}`)).text(),`ai-development-${b.dataset.export}.json`));c.querySelector('[data-prompt]').onclick=async()=>{const prompt=await(await fetch('/api/export/setup-prompt')).text();c.querySelector('#prompt-preview').innerHTML=`<h3>Setup Prompt</h3><textarea readonly>${esc(prompt)}</textarea><div><button class="primary" id="copy-prompt">Copy prompt</button><button class="text-action" id="download-prompt">Download prompt</button></div>`;c.querySelector('#copy-prompt').onclick=()=>navigator.clipboard.writeText(prompt);c.querySelector('#download-prompt').onclick=()=>download(prompt,'ai-development-setup-prompt.txt','text/plain')}}
function shareDefault(recap){const top=[...(recap?.agentSplit||[])].sort((a,b)=>b.sessions-a.sessions)[0],achievement=data.achievements?.[0];return `<section class="share-first"><p>${esc(recap?.title||'THIS MONTH')}</p><h3>${top?`${esc(top.agent)} is leading the recap.`:'Your development story is still loading.'}</h3><span>${fmt(recap?.sessionCount||0)} observed AI sessions${recap?.trackingStartedAt&&recap.id==='all'?` · tracking since ${new Intl.DateTimeFormat(undefined,{month:'short',year:'numeric'}).format(new Date(recap.trackingStartedAt))}`:''}</span>${achievement?`<div class="achievement"><b>${esc(achievement.name)}</b><small>${esc(achievement.description)}</small></div>`:''}</section>`}
async function recapShareDrawer(layer){
  const c=layer.querySelector('#drawer-content');
  c.innerHTML=`<div class="share-toolbar"><div><span class="kicker">RECAP</span><div class="recap-picker" id="recap-picker">${[['today','Today'],['month','This Month'],['all','Since tracking began']].map(([value,label])=>`<button data-period="${value}" aria-pressed="${value==='month'}" class="${value==='month'?'selected':''}">${label}</button>`).join('')}</div></div><div class="share-actions"><button class="text-action share-export" id="export-current" disabled>Export current</button><button class="text-action share-export" id="export-all" disabled>Export all</button><button class="text-action share-export" id="play-slides" disabled>Play slideshow</button></div></div><div id="share-default"><section class="share-first"><p>THIS MONTH</p><h3>Preparing your development story.</h3></section></div><div class="slide-navigator" id="slide-navigator" aria-label="Share story slides"></div><div class="share-workspace"><div class="share-controls"><div><span class="kicker">FORMAT</span><div class="format-picker" id="format-picker">${SHARE_FORMATS.map((item,index)=>`<button class="format-option ${index===0?'selected':''}" data-format="${item.id}" aria-pressed="${index===0}"><i class="ratio ratio-${item.id.replace(':','x')}"></i><strong>${item.label}</strong><small>${item.dimensions}</small></button>`).join('')}</div></div><div><span class="kicker">INCLUDE</span><div id="metric-controls"><p class="quiet">Loading safe metrics…</p></div></div><p class="share-auto-state" id="share-auto-state">Preview updates automatically.</p></div><div class="card-stage" id="share-preview"><span class="quiet">Preparing your share card…</span><div class="slide-stepper"><button id="slide-previous" aria-label="Previous slide">←</button><span id="slide-position">—</span><button id="slide-next" aria-label="Next slide">→</button></div></div></div>`;
  let options=[],snapshot=null,requestId=0,preferences={period:'month',format:'9:16',metrics:[],slide:'intro',previewRevision:0},slideshowTimer=null;
  utilityCleanup=()=>{if(slideshowTimer)clearInterval(slideshowTimer)};
  const controls=c.querySelector('#metric-controls'),stage=c.querySelector('#share-preview'),story=c.querySelector('#share-default'),navigator=c.querySelector('#slide-navigator'),currentExport=c.querySelector('#export-current'),allExport=c.querySelector('#export-all'),play=c.querySelector('#play-slides'),autoState=c.querySelector('#share-auto-state'),position=c.querySelector('#slide-position');
  const selectedMetrics=()=>[...c.querySelectorAll('#metric-controls input:checked')].map(input=>input.value);
  const setPreferences=patch=>{preferences=updateSharePreferences(preferences,patch);return preferences};
  const pngFor=async(next,filename)=>{const svg=await(await fetch(`/api/share/card.svg?snapshot=${next.id}`)).text(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));await new Promise(resolve=>{const img=new Image();img.onload=()=>{const cv=document.createElement('canvas');cv.width=img.width;cv.height=img.height;cv.getContext('2d').drawImage(img,0,0);download(cv.toDataURL('image/png'),filename);URL.revokeObjectURL(url);resolve()};img.src=url})};
  const slideCards=()=>snapshot?.story?.cards||[];
  const renderNavigator=()=>{const cards=slideCards(),current=cards.findIndex(card=>card.id===preferences.slide);navigator.innerHTML=cards.map((card,index)=>`<button data-slide="${card.id}" aria-pressed="${card.id===preferences.slide}" class="${card.id===preferences.slide?'selected':''}"><b>${index+1}</b><span>${esc(card.label)}</span></button>`).join('');(stage.querySelector('#slide-position')||position).textContent=cards.length?`${current+1} / ${cards.length}`:'—';navigator.querySelectorAll('[data-slide]').forEach(button=>button.onclick=()=>{if(button.dataset.slide!==preferences.slide){setPreferences({slide:button.dataset.slide});renderPreview()}})};
  const renderPreview=async()=>{const current=++requestId,metrics=selectedMetrics();setPreferences({metrics});if(!metrics.length){snapshot=null;currentExport.disabled=true;allExport.disabled=true;play.disabled=true;stage.innerHTML=empty('Choose at least one supported metric.');autoState.textContent='Preview paused until a metric is selected.';return;}stage.classList.add('is-updating');autoState.textContent='Updating preview…';try{const response=await fetch('/api/share/snapshot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({metrics,format:preferences.format,period:preferences.period,visual:{slide:preferences.slide},preview:true})}),next=await response.json();if(current!==requestId)return;if(next.error)throw new Error(next.error);snapshot=next;if(!snapshot.story.cards.some(card=>card.id===preferences.slide)){setPreferences({slide:snapshot.story.cards[0].id});return renderPreview()}const cacheBust=`${next.id}-${preferences.previewRevision}`;stage.innerHTML=`<img src="/api/share/card.svg?snapshot=${next.id}&v=${cacheBust}" alt="${esc(next.period.label)} ${esc(next.story.selected)} share slide in ${esc(preferences.format)} format"><small>Frozen ${esc(next.period.label.toLowerCase())} snapshot · public-safe metrics only</small><div class="slide-stepper"><button id="slide-previous" aria-label="Previous slide">←</button><span id="slide-position">—</span><button id="slide-next" aria-label="Next slide">→</button></div>`;stage.querySelector('#slide-previous').onclick=()=>moveSlide(-1);stage.querySelector('#slide-next').onclick=()=>moveSlide(1);renderNavigator();currentExport.disabled=false;allExport.disabled=false;play.disabled=snapshot.story.cards.length<2;autoState.textContent='Preview is current.'}catch{if(current!==requestId)return;snapshot=null;currentExport.disabled=true;allExport.disabled=true;play.disabled=true;stage.innerHTML=empty('Could not prepare the share card. Try another supported metric.');autoState.textContent='Preview unavailable.'}finally{if(current===requestId)stage.classList.remove('is-updating')}};
  const renderControls=(chosen=defaultShareMetrics(options,preferences.period))=>{const selected=new Set(chosen);controls.innerHTML=options.map(metric=>`<label class="metric-choice ${metric.available===false?'unavailable':''}" title="${esc(metric.definition||metric.unavailable||'Public-safe observed metric')}"><input type="checkbox" value="${esc(metric.id)}" ${selected.has(metric.id)?'checked':''}> <span><b>${esc(metric.label)}</b>${metric.available===false?`<small>${esc(metric.unavailable)}</small>`:''}</span></label>`).join('')||empty('No supported share metrics are available in this period.');controls.querySelectorAll('input').forEach(input=>input.addEventListener('change',()=>{preferences.slide='intro';renderPreview()}))};
  const loadPeriod=async()=>{const current=++requestId;controls.innerHTML='<p class="quiet">Loading safe metrics…</p>';stage.innerHTML='<span class="quiet">Preparing your share card…</span>';currentExport.disabled=true;allExport.disabled=true;play.disabled=true;autoState.textContent='Loading period…';try{const response=await(await fetch(`/api/share/options?period=${preferences.period}`)).json();if(current!==requestId)return;options=response.options||[];preferences.slide='intro';story.innerHTML=shareDefault(response.recap);renderControls();await renderPreview()}catch{if(current!==requestId)return;controls.innerHTML=empty('Safe metric options are unavailable.');stage.innerHTML=empty('No preview is available.');autoState.textContent='Preview unavailable.'}};
  const moveSlide=direction=>{const cards=slideCards(),at=cards.findIndex(card=>card.id===preferences.slide),next=cards.at(at+direction);if(next){setPreferences({slide:next.id});renderPreview()}};
  c.querySelector('#recap-picker').addEventListener('click',event=>{const button=event.target.closest('[data-period]');if(!button||button.dataset.period===preferences.period)return;setPreferences({period:button.dataset.period});c.querySelectorAll('[data-period]').forEach(item=>{const selected=item===button;item.classList.toggle('selected',selected);item.setAttribute('aria-pressed',String(selected))});loadPeriod()});
  c.querySelector('#format-picker').addEventListener('click',event=>{const button=event.target.closest('[data-format]');if(!button||button.dataset.format===preferences.format)return;setPreferences({format:button.dataset.format});c.querySelectorAll('[data-format]').forEach(item=>{const selected=item===button;item.classList.toggle('selected',selected);item.setAttribute('aria-pressed',String(selected))});renderPreview()});
  stage.querySelector('#slide-previous').onclick=()=>moveSlide(-1);stage.querySelector('#slide-next').onclick=()=>moveSlide(1);
  currentExport.onclick=()=>snapshot&&pngFor(snapshot,`ai-development-${snapshot.period.id}-${String(snapshot.story.selected).padStart(2,'0')}-${preferences.format.replace(':','x')}.png`);
  allExport.onclick=async()=>{if(!snapshot)return;const cards=[...snapshot.story.cards],active=preferences.slide;allExport.disabled=true;autoState.textContent='Exporting story slides…';for(let index=0;index<cards.length;index++){const card=cards[index],response=await fetch('/api/share/snapshot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({metrics:selectedMetrics(),format:preferences.format,period:preferences.period,visual:{slide:card.id}})}),next=await response.json();if(!next.error)await pngFor(next,`ai-development-${next.period.id}-${String(index+1).padStart(2,'0')}-${card.id}-${preferences.format.replace(':','x')}.png`)}allExport.disabled=false;autoState.textContent='All available slides exported as PNG files.';if(active!==preferences.slide){preferences.slide=active;renderPreview()}};
  play.onclick=()=>{if(slideshowTimer){clearInterval(slideshowTimer);slideshowTimer=null;play.textContent='Play slideshow';return;}play.textContent='Stop slideshow';slideshowTimer=setInterval(()=>{const cards=slideCards(),at=cards.findIndex(card=>card.id===preferences.slide),next=cards[(at+1)%cards.length];setPreferences({slide:next.id});renderPreview()},3200)};
  await loadPeriod();
}
function download(content,name,type='application/json'){const a=document.createElement('a');a.href=content.startsWith('data:')?content:URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click()}
async function saveProjectMetadata(id,changes){const r=await fetch(`/api/projects/${encodeURIComponent(id)}/metadata`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(changes)}),updated=await r.json();if(updated.error)return;data.repositories=(data.repositories||data.projects).map(p=>p.id===id?updated:p);data.projects=data.repositories.filter(p=>p.repositoryClass==='Project');}
function bind(){document.querySelectorAll('[data-project]').forEach(x=>x.onclick=()=>projectDetail(project(x.dataset.project)));document.querySelectorAll('[data-pin]').forEach(x=>x.onclick=async e=>{e.stopPropagation();const p=project(x.dataset.pin);await saveProjectMetadata(p.id,{pinned:!p.pinned,status:p.status,note:p.note,repositoryClass:p.repositoryClass});render()});document.querySelectorAll('[data-capability]').forEach(x=>x.onclick=()=>{detailId=null;capabilityDetail(data.capabilities.find(c=>c.id===x.dataset.capability))});document.querySelectorAll('[data-duplicate]').forEach(x=>x.onclick=()=>duplicateDetail((data.maintenance?.duplicates||[]).find(item=>item.id===x.dataset.duplicate)));document.querySelectorAll('[data-back]').forEach(x=>x.onclick=()=>{detailId=null;view=x.dataset.back||'projects';render()});document.querySelectorAll('[data-nav]').forEach(x=>x.onclick=()=>{detailId=null;view=x.dataset.nav;render()});document.querySelectorAll('[data-expand-context]').forEach(x=>x.onclick=()=>{const id=x.dataset.expandContext;expandedResumeCards.has(id)?expandedResumeCards.delete(id):expandedResumeCards.add(id);render()});document.querySelectorAll('[data-open-agent]').forEach(x=>x.onclick=async e=>{e.stopPropagation();const result=await(await fetch(`/api/projects/${encodeURIComponent(x.dataset.openProject)}/open`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({agent:x.dataset.openAgent})})).json();if(result.error||result.ok===false)alert(result.reason||result.error||'Could not open the agent.')});document.querySelectorAll('[data-handoff]').forEach(x=>x.onclick=async e=>{e.stopPropagation();const result=await(await fetch(`/api/projects/${encodeURIComponent(x.dataset.handoff)}/handoff`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({includeNote:true})})).json();if(result.error){alert(result.error);return;}const preview=document.querySelector('#handoff-preview');if(preview){preview.hidden=false;preview.textContent=result.markdown}try{await navigator.clipboard.writeText(result.markdown)}catch{}download(result.markdown,`${project(x.dataset.handoff)?.name||'project'}.handoff.md`,'text/plain')})}
function render(){if(detailId){const p=project(detailId);if(p){stopMonitor();return projectDetail(p);}detailId=null}if(view!=='overview')stopMonitor();if(view==='overview')overview();else if(view==='projects')projects();else if(view==='capabilities')capabilities();else maintenance()}
async function refreshUI(){try{const next=await(await fetch('/api/data')).json();if(!data||next.summary.lastScanAt!==data.summary.lastScanAt){data=next;live.textContent=`Live · updated ${ago(data.summary.lastScanAt)}`;if(!utility)render()}}catch{}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{detailId=null;view=b.dataset.view;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));render()});document.querySelector('#search').oninput=e=>{term=e.target.value;render()};document.querySelector('#setup').onclick=()=>toggleDrawer('setup');document.querySelector('#share').onclick=()=>toggleDrawer('share');document.querySelector('#rescan').onclick=async()=>{const b=document.querySelector('#rescan');b.textContent='…';await fetch('/api/scan',{method:'POST'});await refreshUI();b.textContent='↻'};data=await(await fetch('/api/data')).json();try{const state=await(await fetch(`/api/live-state?at=${Date.now()}`,{cache:'no-store'})).json();resources=state.system;capacity=state.capacity;liveActivity=state.activity?.events||[];operator=state.operator||null;detectedAgents=state.agents||null}catch{}live.textContent=`Live · updated ${ago(data.summary.lastScanAt)}`;render();setInterval(refreshUI,15000);setInterval(refreshLiveState,2_000);
